mapper.insert:
INSERT INTO TB_COM_MENU_LOG (
    LOG_SEQ, USER_ID, USER_NM, MENU_ID, MENU_NM, MENU_URL, CLICK_DT, USER_IP
) VALUES (
    SEQ_TB_COM_MENU_LOG.NEXTVAL, #{userId}, #{userNm}, #{menuId},
    #{menuNm}, #{menuUrl}, #{clickDt}, #{userIp}
)

mapper.select:
SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT LOG_SEQ, USER_ID, USER_NM, MENU_ID, MENU_NM, MENU_URL, CLICK_DT, USER_IP
        FROM TB_COM_MENU_LOG


                AND (USER_ID LIKE '%' || #{userId} || '%' OR USER_NM LIKE '%' || #{userId} || '%')


                AND (MENU_ID LIKE '%' || #{menuId} || '%' OR MENU_NM LIKE '%' || #{menuId} || '%')


                AND USER_IP LIKE '%' || #{userIp} || '%'


                AND CLICK_DT >= TO_DATE(#{startDt}, 'YYYY-MM-DD')


                AND CLICK_DT < TO_DATE(#{endDt}, 'YYYY-MM-DD') + 1


        ORDER BY CLICK_DT DESC
    ) t WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rn > #{offset}
